// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { dispatchCartUpdated } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8080");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(60000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(`${baseUrl}/logout`);
    await page.goto(`${baseUrl}/product/OLJCESPC7Z`);
    await page.getByRole("button", { name: "Add To Cart" }).click();
    await page.waitForLoadState('networkidle');
    await expect(page.locator('#cart-count-badge')).toHaveText('1');

    // cart-badge.js subscribes to a "cart:updated" event and repaints the badge in place.
    await dispatchCartUpdated(page, 4);
    await expect(page.locator('#cart-count-badge')).toHaveText('4');
    await expect(page.getByRole("link", { name: "Cart icon" })).toContainText("4");
    // Server-rendered cart heading still reads "Cart (1)" and the URL is unchanged,
    // proving the badge repainted in place rather than via a page reload.
    await expect(page.getByTestId("cart-heading")).toContainText("Cart (1)");
    await expect(page).toHaveURL(`${baseUrl}/cart`);

    // count === 0 takes the hide branch of updateBadge().
    await dispatchCartUpdated(page, 0);
    await expect(page.locator('#cart-count-badge')).toBeHidden();
    await expect(page.getByRole("link", { name: "Cart icon" })).not.toContainText("0");
});
